"""Generate a readable engineering walkthrough notebook from the published SQLite outputs."""
import json
from pathlib import Path
import uuid

out=Path(__file__).with_name('VESTIGIUM_DE_WALKTHROUGH.ipynb')
cells=[]
def md(s):cells.append({'id':uuid.uuid4().hex[:8],'cell_type':'markdown','metadata':{},'source':s.strip('\n').splitlines(keepends=True)})
def code(s):cells.append({'id':uuid.uuid4().hex[:8],'cell_type':'code','metadata':{},'execution_count':None,'outputs':[],'source':s.strip('\n').splitlines(keepends=True)})
md('''# VESTIGIUM | Data Engineering Walkthrough\n\n**NASA Space Apps Challenge 2026 · Team Ga Tidur**\n\nThis notebook reads the **outputs** from `build_pipeline.py`. It does not re-process 6 million CSV rows in-memory. It verifies contracts, explores lineage, and demonstrates the query shapes required by the map and temporal dashboard. All dates are UTC; all recorded fires are satellite *detections*, not confirmed fire events.''')
md('''## 1. Setup and reproducibility\n\nRun the pipeline first:\n\n```bash\npython build_pipeline.py --input ../data.zip --output ./outputs\n```\n\nPlace this notebook next to `build_pipeline.py`. The output directory can be changed below.''')
code('''from pathlib import Path\nimport sqlite3, json, csv\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nDATA_DIR = Path('outputs')\nDB = DATA_DIR / 'vestigium_hotspots.sqlite'\nQA = json.loads((DATA_DIR / 'quality_report.json').read_text())\nassert DB.exists(), 'Run build_pipeline.py first'\nprint('Archive SHA-256:', QA['input_sha256'])\nprint('Detected rows:', QA['accepted_presumed_vegetation_detections'])\nprint('Skipped non-vegetation:', QA['excluded_non_vegetation_detections'])\nprint('Rejected invalid rows:', QA['rejected_invalid_rows'])''')
md('''## 2. Data provenance, schema, and sensor inventory\n\nAll input CSVs are hashed and retained in `source_files`. Satellite confidence is intentionally split into `confidence_modis_pct` and `confidence_viirs_label`.''')
code('''con=sqlite3.connect(f'file:{DB.resolve()}?mode=ro', uri=True)\nfiles=pd.read_sql_query('''+'''"""SELECT sensor, nominal_year, filename, source_rows, accepted_type0, excluded_non_vegetation,
 rejected_invalid, first_date_utc, last_date_utc FROM source_files ORDER BY sensor,nominal_year"""'''+''',con)\ndisplay(files.head(8))\nprint('Input files:', len(files))\nprint(files.groupby('sensor')[['source_rows','accepted_type0','excluded_non_vegetation','rejected_invalid']].sum())''')
md('''## 3. Full quality gate reconciliation\n\nCounts must reconcile across the ingestion ledger, the individual points table and each summary. This guards against silent row multiplication or dropping rows during grouping.''')
code('''db_count=con.execute('SELECT COUNT(*) FROM hotspots').fetchone()[0]\nassert db_count == QA['accepted_presumed_vegetation_detections']\nfor filename in ['daily_sensor.csv','monthly_sensor.csv','annual_sensor.csv','monthly_grid.csv','annual_grid.csv']:\n    table=pd.read_csv(DATA_DIR/filename)\n    assert int(table['detection_count'].sum()) == db_count, filename\n    print(filename, len(table), 'groups; reconciles:', int(table['detection_count'].sum()))\nprint('PASS: all five groups reconcile with', db_count, 'detection rows')''')
md('''## 4. Annual detection history, separated by sensor\n\nThese are **not** unique fire events and their absolute counts are not directly comparable across sensors, because spatial resolution, observing conditions and overpass frequency differ.''')
code('''annual=pd.read_csv(DATA_DIR/'annual_sensor.csv')\npivot=annual.pivot(index='year',columns='sensor',values='detection_count')\nax=pivot.plot(figsize=(11,4),marker='o',linewidth=1.5)\nax.set(title='Annual satellite fire detections by sensor (unharmonized)', ylabel='Detected pixels',xlabel='UTC year')\nplt.tight_layout();plt.show()''')
md('''## 5. Monthly history and seasonality\n\nMissing month rows may mean no detections or incomplete observations. The pipeline does **not** invent zeros in the source.''')
code('''monthly=pd.read_csv(DATA_DIR/'monthly_sensor.csv')\nsample=monthly[monthly['year']==2015]\nax=sample.pivot(index='month',columns='sensor',values='detection_count').plot(kind='line',marker='o',figsize=(10,4))\nax.set(title='2015 monthly detection activity',xlabel='UTC month',ylabel='Detected pixels')\nplt.tight_layout();plt.show()''')
md('''## 6. Grid aggregation sanity check\n\nThe map grid is fixed at **0.25 degrees**. Center points are display locations for groups and must not be mistaken for a detected fire's exact pixel centroid.''')
code('''grid=pd.read_csv(DATA_DIR/'annual_grid.csv')\ngrid2015=grid[(grid.year==2015)&(grid.sensor=='MODIS')]\nprint('Active 2015 MODIS cells:', len(grid2015))\nprint('Annual total matches:',grid2015.detection_count.sum(),annual.query("sensor=='MODIS' and year==2015").detection_count.iloc[0])\nax=grid2015.plot.scatter(x='grid_center_lon',y='grid_center_lat',s=grid2015.detection_count.clip(1,1000)/30,alpha=.4,figsize=(10,4))\nax.set(title='2015 MODIS grid centers: sample density view (not individual fire points)',xlabel='Longitude',ylabel='Latitude')\nplt.tight_layout();plt.show()''')
md('''## 7. Individual detections for hover payloads\n\nSpatially restricted SQL protects the browser from millions of points. The dashboard should use clustering or grid aggregates when zoomed out.''')
code('''from example_queries import fetch_hotspots\nspots=fetch_hotspots(str(DB),2015,9,108,-4,119,4,limit=10,sensor='MODIS')\ndisplay(pd.DataFrame(spots))''')
md('''## 8. Sensor confidence semantic checks\n\nMODIS uses a numerical 0–100 confidence scale; VIIRS uses categorical `l/n/h`. Mixing them as a single numerical predictor would be scientifically unsound.''')
code('''assert con.execute("SELECT COUNT(*) FROM hotspots WHERE sensor='MODIS' AND confidence_viirs_label IS NOT NULL").fetchone()[0] == 0\nassert con.execute("SELECT COUNT(*) FROM hotspots WHERE sensor LIKE 'VIIRS%' AND confidence_modis_pct IS NOT NULL").fetchone()[0] == 0\nprint('Sensor-specific confidence storage: PASS')''')
md('''## 9. Connection to NASA harmonization and social impact module\n\nThis ETL is **not** sensor harmonization. It provides provenance, temporal records, spatial bins and a stable query substrate. The next step is comparing overlapping MODIS/VIIRS observation windows with coverage corrections and held-out evaluation. The data do **not** provide trustworthy labels for intentional vs natural ignition.\n\nFor long-term land changes, add distinct area-burned and land-cover products, including spatial overlays and documented time-alignment uncertainty. Do not treat a hotspot point as a burned-area polygon.''')
code('''con.close()\nprint('Completed VESTIGIUM Data Engineering walkthrough.')''')
nb={'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3'}},'nbformat':4,'nbformat_minor':5}
out.write_text(json.dumps(nb,indent=1),encoding='utf-8')
print(out, len(cells),'cells')
